-- ============================================================
-- PRCP 数据库核心表样本数据
-- 数据库: prcp_db
-- 生成日期: 2026-09-29
-- 生成方式: mysqldump --no-create-info --complete-insert
--
-- 包含 13 张核心表的样本数据:
--   系统表: sys_user, sys_role, sys_dict, sys_dict_item
--   账户册: prcp_coa_scheme, prcp_coa_node
--   指标体系: prcp_kpi_scheme, prcp_kpi_definition, prcp_kpi_value
--   余额数据: prcp_data_balance, prcp_data_basic
--   反算:    prcp_reverse_scheme, prcp_reverse_run
--
-- 注意: 数据使用 INSERT ... VALUES 单行形式（可读性好但文件较大）
--       重置数据时建议先 TRUNCATE 或 DELETE
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;



LOCK TABLES `prcp_coa_scheme` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_coa_node` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_kpi_scheme` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_kpi_definition` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_kpi_value` WRITE;


UNLOCK TABLES;

LOCK TABLES `sys_user` WRITE;


UNLOCK TABLES;

LOCK TABLES `sys_role` WRITE;


UNLOCK TABLES;

LOCK TABLES `sys_dict` WRITE;


UNLOCK TABLES;

LOCK TABLES `sys_dict_item` WRITE;


UNLOCK TABLES;





LOCK TABLES `prcp_data_balance` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_data_basic` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_reverse_scheme` WRITE;


UNLOCK TABLES;

LOCK TABLES `prcp_reverse_run` WRITE;


UNLOCK TABLES;

